import{_ as a,o as e,c as s,ag as i}from"./chunks/framework.C9sp7nFj.js";const m=JSON.parse('{"title":"GetSimDI8421 获取8421码虚拟数字量输入","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/4. IO 指令/GetSimDI8421.md","filePath":"3. 指令/4. IO 指令/GetSimDI8421.md","lastUpdated":1778862643000}'),d={name:"3. 指令/4. IO 指令/GetSimDI8421.md"};function r(n,t,o,h,l,p){return e(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="getsimdi8421-获取8421码虚拟数字量输入" tabindex="-1">GetSimDI8421 获取8421码虚拟数字量输入 <a class="header-anchor" href="#getsimdi8421-获取8421码虚拟数字量输入" aria-label="Permalink to &quot;GetSimDI8421 获取8421码虚拟数字量输入&quot;">​</a></h1><p>该指令用于获取一段连续的**虚拟数字量输入（SimDI）**端口状态。系统将这些端口的电平状态（0 或 1）看作一段二进制数据（以起始端口作为最低有效位 LSB），并将其转换为十进制数返回给指定的变量。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p><code>GetSimDI8421(BEGINPORT, ENDPORT, RETURNVALUE)</code></p><p><code>GetSimDI8421(起始虚拟端口, 结束虚拟端口, 返回值变量)</code></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>BEGINPORT</td><td>int</td><td>该段连续虚拟 DI 端口的起始端口号</td><td>必填</td></tr><tr><td>ENDPORT</td><td>int</td><td>该段连续虚拟 DI 端口的结束端口号</td><td>必填</td></tr><tr><td>RETURNVALUE</td><td>INT 变量</td><td>存储转换结果的变量</td><td>必填</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GetSimDI8421</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, INT1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>将第 <strong>9</strong> 到第 <strong>16</strong> 号虚拟数字量输入端口的状态视作二进制数，将其转化为十进制数后返回给变量 <strong>INT1</strong>。</p><hr><p><strong>💡 逻辑说明：</strong></p><p>如果端口 9 为 1，端口 10 为 1，其余（11-16）为 0，则二进制表现为 <code>00000011</code>，转换后返回给 <code>INT1</code> 的十进制值即为 <strong>3</strong>。</p>',16)])])}const g=a(d,[["render",r]]);export{m as __pageData,g as default};
